function compute(inputs){
  const A = inputs.A;
  const d = inputs.d;
  const N = 4;
  // compute out-degrees
  const outdeg = A.map(row => row.reduce((a,b)=>a+b,0));
  // handle dangling nodes: if outdeg=0, distribute uniformly
  const M = A.map((row,i)=>{
    if(outdeg[i]===0){
      return Array(N).fill(1/N);
    } else {
      return row.map(val => val / outdeg[i]);
    }
  });
  // power iteration
  let r = Array(N).fill(1/N);
  const maxIter = 100;
  const tol = 1e-10;
  let iter = 0;
  for(iter=0; iter<maxIter; iter++){
    const r_new = Array(N).fill((1-d)/N);
    for(let i=0; i<N; i++){
      for(let j=0; j<N; j++){
        r_new[j] += d * r[i] * M[i][j];
      }
    }
    // check convergence
    let diff = 0;
    for(let i=0; i<N; i++) diff += Math.abs(r_new[i]-r[i]);
    r = r_new;
    if(diff < tol) break;
  }
  // normalize to sum 1 (should already)
  const sumR = r.reduce((a,b)=>a+b,0);
  const rNorm = r.map(v => v/sumR);
  // table of intermediate quantities
  const table = {
    columns: ["Page", "Out-degree", "r_i"],
    rows: rNorm.map((val,i)=>["P"+(i+1), outdeg[i], val.toFixed(4)])
  };
  // flow diagram
  const nodes = rNorm.map((val,i)=>({id: "P"+(i+1), label: "P"+(i+1), value: val}));
  const edges = [];
  for(let i=0; i<N; i++){
    for(let j=0; j<N; j++){
      if(A[i][j]===1){
        edges.push({from: "P"+(i+1), to: "P"+(j+1), label: "", value: 1});
      }
    }
  }
  const flow = {nodes, edges};
  // insight
  const maxIdx = rNorm.indexOf(Math.max(...rNorm));
  const minIdx = rNorm.indexOf(Math.min(...rNorm));
  const insight = `With d=${d.toFixed(2)}, the highest rank is P${maxIdx+1} (${rNorm[maxIdx].toFixed(3)}) and the lowest is P${minIdx+1} (${rNorm[minIdx].toFixed(3)}). ` +
    (d===0 ? "At d=0, all pages have equal rank because the surfer always jumps randomly." :
     d===1 ? "At d=1, the surfer never jumps; ranks depend only on link structure." :
     "Higher d means the surfer follows links more often, so pages with many incoming links tend to get higher rank.");
  return {r: rNorm, table, flow, insight};
}
